// register.go wires every built-in plugin into the plugin registry.
//
// RegisterAll is called at startup (from both CLI and GUI entry points)
// to populate the registry with all supported tools. The registration
// order is:
//
//  1. Java — the only plugin with custom ArchiveFor logic (pinned
//     Temurin archives from the manifest)
//  2. Generic tools — generated by iterating the full manifest catalog:
//     every catalog tool becomes a plugin.Generic, so any manifest
//     (M1 core, M2 languages, M3 Android toolchain / build tools,
//     Flutter, package managers, Spec 023 ide/agent/harness, ...) is
//     registered automatically without code changes.  Tools backed by
//     a dedicated plugin (java) and non-tool YAML entries (index.yaml)
//     are skipped.
//  3. User-installed Lua plugins — loaded from <XMDevDir>/plugins/
//     (single source with `xdev plugin install`), supporting both
//     xdev-native format and vfox-compatible format
//
// Tools that need a custom install sub-directory (e.g. Android SDK
// components that live under android/) set install_root in their
// manifest, which Generic.InstallDir honors.
package cli

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
	"runtime"
	"strings"

	"github.com/xmdemt/xdev/internal/manifest"
	"github.com/xmdemt/xdev/internal/plugin"
	"github.com/xmdemt/xdev/internal/plugins/java"
)

// customPluginNames 列出由专用插件实现（而非 Generic）的内置工具。
// 通用注册循环会跳过它们，保证专用逻辑（如 java 的固定 Temurin
// 资源解析）不被 Generic 覆盖。
var customPluginNames = map[string]bool{
	"java": true,
}

// RegisterAll wires every built-in plugin into r, using the
// manifest.Tools loaded from disk.
//
// 2026-10-25（架构收口）：装配逻辑已下沉到 plugin.BuildRegistry ——
// 修复前它在这里、cli/hook.go、shim/shim.go 三处各写一遍，且
// 后两处只 NewGeneric、**缺 Lua/vfox 插件**，导致插件型工具的 env 注入
// 与项目级版本切换静默失效。本函数保留是因为它额外注册 Java 专用插件
// （唯一的自定义 ArchiveFor 实现），其余全部委托。
func RegisterAll(r *plugin.Registry, catalog *manifest.Catalog) {
	// 1. 专用插件先注册 — Java 是唯一带自定义 ArchiveFor 逻辑的插件。
	//    必须先于 Generic，否则 Generic 会先占位（"资源解析不被 Generic 覆盖"）。
	if t, ok := catalog.Tool("java"); ok {
		r.Register(java.New(t))
	}

	// 2. 其余全部交给统一装配（Generic + 用户 Lua/vfox 插件）。
	//    BuildRegistry 会跳过已有专用插件的工具名。
	//    传入 pluginsReadDir 而非让 plugin 包直调 os.ReadDir：
	//    cli 的 P2-31 守卫靠这个包级接缝断言「目录只扫一次」。
	hintLegacyPluginsDir()
	for _, p := range plugin.BuildRegistryWithReadDir(catalog, pluginsDir(), customPluginNames, pluginsReadDir).All() {
		r.Register(p)
	}
}

// isRegisterableTool 报告 t 是否为可安装的真实工具：至少要有
// display_name、latest/lts、版本列表或 remote 之一。全空的条目
// （如 manifests/index.yaml 这类目录索引）没有可安装内容，跳过。
func isRegisterableTool(t *manifest.Tool) bool {
	return t.DisplayName != "" || t.Latest != "" || t.LTS != "" ||
		len(t.VersionList) > 0 || t.Remote.Type != ""
}

// pluginsDirFn resolves the canonical user plugin directory. It is a
// package-level variable so tests can replace it without touching global
// config state (ticket 04).
//
// Ticket 04 / P0-06 single source of truth: registration scans and
// `xdev plugin install`/`create` write the SAME directory —
// Cfg().Core.XMDevDir/plugins (identical to pluginDir() in plugin.go).
// The previous implementation scanned $XMDEV_HOME or ~/.xdev/plugins,
// so in default deployments (no XMDEV_HOME env) installed plugins were
// never loaded.
var pluginsDirFn = func() string {
	return filepath.Join(Cfg().Core.XMDevDir, "plugins")
}

// pluginsDir returns the user plugin directory (read side of the single
// source; the write side is pluginDir() in plugin.go).
func pluginsDir() string { return pluginsDirFn() }

// legacyPluginsDir returns the pre-single-source plugin directory that
// older xdev releases scanned ($XMDEV_HOME/plugins or ~/.xdev/plugins).
func legacyPluginsDir() string {
	home := os.Getenv("XMDEV_HOME")
	if home == "" {
		if runtime.GOOS == "windows" {
			home = filepath.Join(os.Getenv("USERPROFILE"), ".xdev")
		} else {
			home = filepath.Join(os.Getenv("HOME"), ".xdev")
		}
	}
	return filepath.Join(home, "plugins")
}

// hintLegacyPluginsDir logs a migration hint when the legacy plugin
// directory still holds entries while the canonical directory does not
// exist. Plugins are never moved automatically: a silent double scan
// could register duplicates. Registration itself always uses the
// canonical directory (pluginsDir).
func hintLegacyPluginsDir() {
	dir := pluginsDir()
	if _, err := os.ReadDir(dir); err == nil {
		return // canonical dir exists (even if empty) — nothing to hint
	}
	legacy := legacyPluginsDir()
	if dir == legacy {
		return // same path (XMDEV_HOME deployment) — nothing to migrate
	}
	entries, err := os.ReadDir(legacy)
	if err != nil || len(entries) == 0 {
		return
	}
	log.Printf("[plugin] 迁移提示：检测到旧插件目录 %s 仍含 %d 个条目，而当前插件目录 %s 不存在。请手动把需要的 .lua 插件复制到 %s 后使用（不自动搬移，以避免双扫描注册重复）。", legacy, len(entries), dir, dir)
}

// pluginsReadDir 是 os.ReadDir 的测试接缝（票 39 / P2-31 守卫：目录只扫
// 一次）。生产路径不使用替换值。
var pluginsReadDir = os.ReadDir

// registerUserPlugins 扫描插件目录一次，把其中每个 .lua 注册到 r。
//
// 票 39 / P2-31（N-09）——修复前是两个平行函数（registerLuaPlugins +
// registerVfoxPlugins），各自 os.ReadDir 一次、各自 plugin.NewLuaEngine()
// 一次、各自对该文件 DoFile 一次：
//
//   - 一个文件被 DoFile 两次（顶层代码执行两遍；两次都可能产生副作用，
//     且引擎里缓存两份 VM）；
//   - xdev 插件先注册成功、随后 vfox 侧再加载一遍：vfox 加载失败是静默
//     `continue`，写坏的 vfox 插件完全没有任何提示，用户只能看到"插件没
//     生效"。
//
// 现改为：一次扫描 + 一个引擎，每个文件**先按 xdev 原生格式加载**，失败再
// 按 vfox 兼容格式加载；加载成功的文件只 DoFile 一次。两种格式都失败时把
// 两个错误一起报出来（不再静默）。注册冲突警告与旧目录迁移提示的既有语义
// 保持不变（hintLegacyPluginsDir 仍在 RegisterAll 里先执行）。
func registerUserPlugins(r *plugin.Registry) {
	dir := pluginsDir()
	entries, err := pluginsReadDir(dir)
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "warning: failed to read plugins dir %s: %v\n", dir, err)
		}
		return
	}

	engine := plugin.NewLuaEngine()
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".lua") {
			continue
		}
		path := filepath.Join(dir, e.Name())

		// 1) xdev 原生格式（多数插件）。成功即注册，不再尝试 vfox
		//    ——"成功加载的文件只 DoFile 一次"。
		p, xdevErr := engine.LoadPlugin(path)
		if xdevErr == nil {
			if _, exists := r.Get(p.Name()); exists {
				fmt.Fprintf(os.Stderr, "warning: Lua plugin %s conflicts with built-in plugin, skipping\n", p.Name())
				continue
			}
			r.Register(p)
			continue
		}

		// 2) vfox 兼容格式（PLUGIN.info + install()/env_keys()）。
		vfoxPlugin, vfoxErr := engine.LoadVfoxPlugin(path)
		if vfoxErr != nil {
			// 修复前这里是静默 continue——两种格式都读不出来时必须让用户
			// 看到原因（两个错误都打印，便于判断是格式写错还是脚本报错）。
			fmt.Fprintf(os.Stderr, "warning: failed to load Lua plugin %s: %v; vfox format also failed: %v\n",
				e.Name(), xdevErr, vfoxErr)
			continue
		}
		if _, exists := r.Get(vfoxPlugin.Name()); exists {
			fmt.Fprintf(os.Stderr, "warning: vfox plugin %s conflicts with existing plugin, skipping\n", vfoxPlugin.Name())
			continue
		}
		r.Register(vfoxPlugin)
		fmt.Fprintf(os.Stderr, "info: loaded vfox plugin %s from %s\n", vfoxPlugin.Name(), e.Name())
	}
}
